// Code generated by rig. DO NOT EDIT.
//
// This file is rewritten on every run. Put changes in the service layer.

package api

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/simonjanss/rig/observe"
	"github.com/simonjanss/rig/runtime/serve"
)

// Tasks are the subcommands this project's configuration already decided,
// merged with the ones only this application can write.
//
//	Tasks: api.Tasks(map[string]serve.Task{
//		"migrate": migrate.Apply(migrations, migrate.Options{Log: os.Stdout}),
//	}),
//
// Same bargain as [MigrationSources]: the argument is this application's half
// and it wins, so a project that wants a different sweep registers one under
// the same name rather than editing a generated file. What is generated is
// what has no decision left in it — each entry below is one call whose every
// number came from rig.yaml.
//
// Nothing schedules any of them. They are subcommands of the binary the server
// is, so that the job and the server it ships with read one configuration and
// connect the same way; what runs them hourly is the deployment's business.
func Tasks(own map[string]serve.Task) map[string]serve.Task {
	out := map[string]serve.Task{
		// The records of writes that carried an Idempotency-Key. Zero takes the
		// default retention, a day.
		"prune-idempotency": IdempotencyPruner(0),

		// Uploads whose row never arrived, and file rows whose restore window has
		// closed.
		"sweep-files": func(ctx context.Context, pool *pgxpool.Pool) error {
			return FileSweeper(NewFiles(pool))(ctx, pool)
		},

		// Presence rows past their window, for an operator who would rather this were
		// a cron entry than the goroutine [StartPresenceSweeper] runs. Unlike a
		// dispatcher it is not the guarantee behind anything: who is present is
		// decided by whoever is reading, against the clock. This only keeps the table
		// — and every new subscriber's first fetch — from carrying yesterday.
		"sweep-presence": func(ctx context.Context, pool *pgxpool.Pool) error {
			return PresenceSweep(NewPresenceSweeper(NewPresence(pool)))(ctx, pool)
		},
	}

	// The application's half last, so a name it uses twice is its own rather than
	// a silent argument with a generated file.
	for name, task := range own {
		out[name] = task
	}
	return out
}

// How long each shutdown step rig registers may take.
//
// Each has a limit of its own rather than a share of the whole, because a step
// that cannot finish must not be able to spend the budget the steps after it
// will need. They are also what [ShutdownBudget] is made of, which is why they
// are constants rather than literals at the call sites: the number a step is
// registered with and the number the budget counts for it are one number.
const (
	// The trace flush.
	tracesShutdown = 5 * time.Second
	// The notification engine.
	notificationsShutdown = 15 * time.Second
	// The presence sweeper.
	presenceShutdown = 5 * time.Second
	// The live subscriptions.
	shapesShutdown = 5 * time.Second
	// The auth cache's invalidation channel.
	authShutdown = 5 * time.Second

	// What is left for the requests still in flight once the steps above have had
	// theirs.
	//
	// serve refuses a budget its parts do not fit inside, and warns about one that
	// is exactly spoken for. That warning is the failure this exists to prevent: a
	// shutdown that finishes rig's housekeeping and drops whatever was being
	// answered is a rolling deploy with dropped requests.
	shutdownHeadroom = 10 * time.Second
)

// ShutdownBudget is what this project's own shutdown needs of
// [github.com/simonjanss/rig/runtime/serve.Config.MaxShutdown].
//
// For this project that is 45s: 5s for the trace flush, 15s for the
// notification engine, 5s for the presence sweeper, 5s for the live
// subscriptions, 5s for the auth cache's invalidation channel and 10s left
// over.
//
// **Read it, then write it down.** There is no default and nothing settles it:
// a serve.Config that leaves MaxShutdown out is refused before the server
// listens, because this is the one number in it that leaves the program. So
// the number is one to look up once and write out:
//
//	MaxShutdown: 45 * time.Second
//
// MaxShutdown is the one field in that struct that leaves the program — it
// is what belongs in Kubernetes' terminationGracePeriodSeconds — and whoever
// writes the manifest should be able to read it off the struct rather than run
// the binary or add up a sum spread over three files. A project with closers
// of its own adds theirs to the total above and writes that:
//
//	MaxShutdown: 50 * time.Second // 45s here, plus 5s for a closer of my own
//
// A literal is not a number waiting to drift. serve.App adds up every step
// actually registered, before the server listens, and refuses a budget that
// cannot hold them with the parts named — so a number left stale by a new
// block is a process that will not start and says which parts no longer fit. A
// wrong number that fails loudly at boot is worth more than a right one nobody
// can read.
//
// Every step this project's configuration registers is counted here, including
// one in a process that never starts it — a `Tasks:` entry never reaches the
// mount closure, and serve.Config is built before it either way. It is a
// maximum, so counting a step that is not there costs nothing but headroom.
func ShutdownBudget() time.Duration {
	return tracesShutdown + notificationsShutdown + presenceShutdown + shapesShutdown + authShutdown + shutdownHeadroom
}

// Process is what this application's rig.yaml says about the process around
// its server: where the log lines go, where the spans go, and rig's own page
// over both.
//
// It is generated rather than written because every part of it came from a
// block in rig.yaml, and because the three have an order between them that
// nothing in a main function says out loud. What is left for a main is the two
// ends:
//
//	process, err := api.NewProcess()
//	if err != nil {
//		slog.Error("cannot set this process up", "error", err)
//		os.Exit(1)
//	}
//
//	serve.Main(process.Configure(serve.Config{ /* ... */ }),
//		func(ctx context.Context, app *serve.App) (http.Handler, error) {
//			process.Attach(app)
//			// ...
//		})
//
// A project that wants something else — a narrower level on the log file, a
// path that is not an environment variable's to choose — writes those lines
// itself instead. [Tracing] and [Monitoring] stay exported for exactly that:
// this is the arrangement rig.yaml describes, not the only one it allows.
type Process struct {
	tracing *observe.Provider
	logs    *observe.Logs
	page    *observe.Page
	logger  *slog.Logger
}

// NewProcess opens the log file and installs the tracer provider, then builds
// rig's monitoring page over both.
//
// In that order, and the order is the reason this is one call rather than
// three. The sink has to exist before the logger that tees into it, because
// the lines written while starting up are lines worth having. The provider has
// to exist before the page, because the page reads the span file that provider
// is writing and two places naming that path would be one too many. And all of
// it has to exist before serve.Config is built, because fields of it come out
// of here and the mount closure runs only once the configuration is complete.
//
// Nothing here opens a port, talks to a collector or touches the database, so
// it takes no context and there is nothing to bound. Nothing is written and
// nothing exported unless the environment says where — $RIG_LOG_FILE,
// $RIG_TRACE_FILE, $OTEL_EXPORTER_OTLP_ENDPOINT — and with none of them set
// this costs one branch per log call and still hands out trace identifiers
// that are real, which is what the request id in every error body is.
//
// It returns an error rather than exiting, even though the caller has no
// logger to report one with yet: a path nothing can write, a monitoring
// password too short to be worth having and a span file that is also the log
// file are configuration mistakes, and which of them it was is worth saying.
// Deciding a process's exit code is not a generator's to do.
func NewProcess() (*Process, error) {
	logs, err := observe.OpenLogs(observe.LogConfig{})
	if err != nil {
		return nil, fmt.Errorf("open the log file: %w", err)
	}

	// context.Background rather than a startup budget: setting a provider up talks
	// to nothing.
	tracing, err := observe.Setup(context.Background(), Tracing())
	if err != nil {
		return nil, fmt.Errorf("set tracing up: %w", err)
	}

	// The one part of the page's configuration that is an object rather than a
	// value, which is why it is filled here and not in [Monitoring]: the page
	// reading the file this handler is writing is what makes a request and the
	// lines it wrote one view, and two places naming that path would be one too
	// many.
	monitoring := Monitoring()
	monitoring.Logs = logs

	page, err := tracing.Page(monitoring)
	if err != nil {
		return nil, fmt.Errorf("build the monitoring page: %w", err)
	}

	return &Process{
		tracing: tracing,
		logs:    logs,
		page:    page,
		// Stderr, and the file behind it. The two keep their own levels: this one
		// stays at whatever the default handler is set to, and the file keeps debug
		// — which is where rig's request line is, so there are requests to read back
		// without this process printing one per request to a terminal nobody is
		// watching.
		logger: slog.New(observe.Tee(slog.Default().Handler(), logs.Handler())),
	}, nil
}

// Page is rig's monitoring page, for an application with somewhere else to
// name it — a link to it from a page of its own, most likely, since the page
// is on an origin of its own and a relative href does not reach it.
// [github.com/simonjanss/rig/observe.Page.Addr] and BasePath are the halves to
// build that link out of.
//
// Serving it is [Process.Configure]'s business rather than this one's.
func (p *Process) Page() *observe.Page { return p.page }

// LogHandler is the sink the monitoring page reads, as a handler to tee beside
// one of your own:
//
//	Logger: slog.New(observe.Tee(myHandler, process.LogHandler()))
//
// [Process.Configure] does exactly that with slog.Default's handler, for an
// application with no opinion about it — which is most of them. This is for
// one that has, and it is what keeps setting Logger yourself from being a file
// with nothing in it.
func (p *Process) LogHandler() slog.Handler { return p.logs.Handler() }

// Configure fills in the half of a serve.Config that comes out of
// [NewProcess], and leaves anything already set alone. What it sets, and what
// setting it yourself costs, is one paragraph each.
//
// Monitor and MonitorAddr are the page, on a listener of its own in this same
// process. Both are zero when the page is unarmed, and then no second port is
// opened at all — which is what a laptop with no password set gets. They are
// filled as a pair or not at all, because either one alone is a page somebody
// believes is running.
//
// Logger is stderr and the file the page reads, both, each at its own level.
// Set it yourself and the page has nothing to list unless [Process.LogHandler]
// is teed into what you set.
//
// Pool is a span per statement, from the connection rather than from the
// generated code — so a tracer sees every query, including the ones rig's
// own background work runs and the ones no generator wrote.
//
// OnExit is [Process.Close], which is why a main function does not write one.
// serve.Main exits, and `defer` does not survive os.Exit: a flush deferred in
// main runs when the server stopped cleanly and is skipped on the three paths
// where something went wrong — a task that failed, a boot that failed, a
// subcommand that does not exist. Those are the runs whose spans somebody
// actually wants.
//
// MaxShutdown is deliberately not one of them, and nothing else fills it
// either. It is the project's to state: the number an operator copies into
// terminationGracePeriodSeconds should be readable off the struct rather than
// out of a call, and a value this method supplied would be one nobody wrote
// deciding how long something outside this process waits before SIGKILL.
// [ShutdownBudget] is what to write.
func (p *Process) Configure(cfg serve.Config) serve.Config {
	if cfg.Monitor == nil && cfg.MonitorAddr == "" {
		cfg.Monitor = p.page.Handler()
		cfg.MonitorAddr = p.page.Addr()
	}
	if cfg.Logger == nil {
		cfg.Logger = p.logger
	}
	if cfg.Pool == nil {
		cfg.Pool = observe.Pool
	}
	if cfg.OnExit == nil {
		cfg.OnExit = p.Close
	}
	return cfg
}

// Attach registers what this process needs of the server, on the App the mount
// function is given.
//
//	process.Attach(app)
//
// It is the mount closure's half rather than main's for two reasons that are
// really one: an App is the first thing there is to register a shutdown step
// with, and a logger already writing to the log file is the right place to say
// what is not running.
func (p *Process) Attach(app *serve.App) {
	// A limit of its own, because a flush to a collector that is not answering
	// must not spend the whole shutdown budget. [Process.Close] is the other half
	// of the pair — the half a task run reaches.
	app.CloseWithin("traces", tracesShutdown, p.tracing.Shutdown)

	// Said rather than left to be discovered. An address and a password are a
	// deployment's to set, so a missing one is not a failure: it is an environment
	// saying it does not want this. Empty for no visible reason is the outcome
	// worth spending a line to avoid.
	if why := p.page.Unarmed(); why != "" {
		app.Logger.Info("monitoring page not listening", "reason", why)
	}
	if why := p.logs.Unarmed(); why != "" {
		app.Logger.Info("monitoring page has no log lines to read", "reason", why)
	}
}

// Close flushes whatever tracing has buffered, and is the half of that a task
// run reaches.
//
// [Process.Configure] sets it as serve.Config.OnExit, so a main function does
// not call it: serve.Main runs it on every way out, including the ones that
// exit non-zero, where a deferred call would not have run at all.
//
// Both ways out of this process reach a provider built in [NewProcess], and
// only one of them reaches [Process.Attach]. A `Tasks:` entry never reaches
// the mount closure — serve.Main runs the task and returns — so without
// this an hourly job with $RIG_TRACE_FILE set would open a second rotating
// writer on the span file the server is already rotating, and then drop
// everything it buffered on the way out. The server path runs both halves and
// the second finds nothing left to do: Provider.Shutdown is idempotent.
//
// The log sink is not closed here, and that is not an omission. Its writes are
// unbuffered, so there is nothing to flush, and the last lines a server writes
// are written during its shutdown — a step that closed the file would be a
// step that threw them away.
//
// Nothing is returned because there is nowhere left to return it to. A failure
// goes to the logger [Process.Configure] hands the server, which is stderr and
// the log file both.
func (p *Process) Close() {
	flushing, cancel := context.WithTimeout(context.Background(), tracesShutdown)
	defer cancel()

	if err := p.tracing.Shutdown(flushing); err != nil {
		p.logger.Error("cannot flush the spans", "error", err)
	}
}
